   -- HDL Embedded Text Block 2 eb2
   -- eb2 2                                        
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_KY7 <= '0';
   	elsif rising_edge(Clk) then
   		if(REG_CAP_MODE = X"11") then
   			REG_KY7 <= '1';
   		else
   			REG_KY7 <= '0';
   		end if;
   	end if;
   end process;
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_KY65 <= "00";
   	elsif rising_edge(Clk) then
   		if(CMA_Sen_State = X"04") then
   			REG_KY65 <= "01";
   		elsif(CMA_Sen_State = X"11") then
   			REG_KY65 <= "10";
   		else
   			REG_KY65 <= "00";
   		end if;
   	end if;
   end process;
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_KY43 <= "00";
   	elsif rising_edge(Clk) then
   		if(CMB_Sen_State = X"04") then
   			REG_KY43 <= "01";
   		elsif(CMB_Sen_State = X"11") then
   			REG_KY43 <= "10";
   		else
   			REG_KY43 <= "00";
   		end if;
   	end if;
   end process;
   
   
   process(Clk) begin
   	if rising_edge(Clk) then
   		REG_KY2  <= CMA_POWER and CMB_POWER;
   	end if;
   end process;
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_KY1 <= '0';
   	elsif rising_edge(Clk) then
   		if(Rsp_Start = '1') and (Rsp_State = "00") then
   			REG_KY1 <= not REG_KY1;
   		end if;
   	end if;
   end process;
   
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		Heart_Cnt <= (others => '0');
   		REG_KY0   <= '0';
   	elsif rising_edge(Clk) then
   		if(ClkMs_En = '1') then
   			if(Heart_Cnt = conv_std_logic_vector(999,12)) then
   				Heart_Cnt <= (others => '0');
   				REG_KY0   <= not REG_KY0;
   			else
   				Heart_Cnt <= Heart_Cnt + X"001";
   			end if;
   		end if;
   	end if;
   end process;
   
   
   

   -- HDL Embedded Text Block 4 eb4
   -- eb2 2                                        
   process(State_c) begin
   	
   	if(State_c = ST_YC_AWADDR_A)  then   -- 4  16
   		AWADDR <= X"00";
   		AWLEN  <= X"06";
   		AWVALID <= '1';
   	elsif(State_c = ST_YC_AWADDR_B)  then   -- 20 16
   		AWADDR <= X"07";
   		AWLEN  <= X"0F";
   		AWVALID <= '1';
   	elsif(State_c = ST_YC_AWADDR_C)  then   -- 36 16
   		AWADDR <= X"17";
   		AWLEN  <= X"0F";
   		AWVALID <= '1';
   	elsif(State_c = ST_YC_AWADDR_D)  then   -- 52 6
   		AWADDR <= X"27";
   		AWLEN  <= X"05";
   		AWVALID <= '1';
   	else
   		AWADDR <= X"00";
   		AWLEN  <= X"00";
   		AWVALID <= '0';
   	end if;
   
   end process;
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		WDATA  <= X"00";
   	elsif rising_edge(Clk) then
   		case State_c is 
   			when ST_REG13   	=> 
   				WDATA  <= REG_KY;
   			when ST_REG14   	=>
   				WDATA  <= REG_VERSION;
   			when ST_REG15		=>
   				WDATA  <= REG_CAP_MODE;
   			when ST_REG16		=> 
   				WDATA  <= REG_ERR(15 downto 8);
   			when ST_REG17		=> 
   				WDATA  <= REG_ERR(7 downto 0);
   			when ST_REG18		=>
   				WDATA  <= REG_CX(15 downto 8);
   			when ST_REG19 =>
   				WDATA  <= REG_CX(7 downto 0);
   			when ST_REG20	=>
   				WDATA  <= REG_CMD_NUM(15 downto 8);
   			when ST_REG21	=>
   				WDATA  <= REG_CMD_NUM(7 downto 0);
   			when ST_REG22	=>
