   				WDATA  <= REGB_KC_X(15 downto 8);
   			when ST_REG46  =>
   				WDATA  <= REGB_KC_X(7 downto 0);
   				
   			when ST_REG47  =>
   				WDATA  <= REGB_KC_Y(15 downto 8);
   			when ST_REG48  =>
   				WDATA  <= REGB_KC_Y(7 downto 0);
   			when ST_REG49  =>
   				if(REGB_CAP_ENABLE = '1') then
   					WDATA <= X"55";
   				else
   					WDATA <= X"00";
   				end if;
   			when ST_REG50  =>
   				WDATA <= REGB_FRAME_FREQ;
   				
   			when ST_REG51  =>
   				if(CMA_POWER = '1') then
   					WDATA <= X"11";
   				else
   					WDATA <= X"00";
   				end if;
   			when ST_REG52  =>
   				if(CMB_POWER = '1') then
   					WDATA <= X"11";
   				else
   					WDATA <= X"00";
   				end if;
   			when ST_REG53	=> 
   				if(REGB_GAIN_MODE = '1') then
   					WDATA <= X"11";
   				else 
   					WDATA  <= X"22";
   				end if;
   			when ST_REG54	=> 
   				WDATA  <= REGB_EXPOTIME(15 downto 8);
   			when ST_REG55	=> 
   				WDATA  <= REGB_EXPOTIME(7 downto 0);
   			when ST_REG56	=> 
   				WDATA  <= REGB_GAIN_VAL;
   			when ST_REG57	=> 
   				WDATA  <= REGB_STATE;
   								
   			when others =>
   				WDATA  <= X"00";
   		end case;
   	end if;
   end process;
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		WVALID_b <= '0';
   	elsif rising_edge(Clk) then
   		case State_c is 
   			when ST_REG13 =>
   				WVALID_b <= '1';
   			when ST_REG20 =>
   				WVALID_b <= '1';
   			when ST_REG36 =>
   				WVALID_b <= '1';
   			when ST_REG52 =>
   				WVALID_b <= '1';
   			--
   			when ST_WAIT_A =>
   				WVALID_b <= '0';
   			when ST_WAIT_B =>
   				WVALID_b <= '0';
   			when ST_WAIT_C =>
   				WVALID_b <= '0';
   			when ST_WAIT_D =>
   				WVALID_b <= '0';
   			when others =>
   				WVALID_b <= WVALID_b;
   		end case;
   	end if;
   end process;
   
   WVALID <= WVALID_b;
   
   
      process(Reset, Clk) begin
      	if(Reset = '1') then
      		WLAST <= '0';
      	elsif rising_edge(Clk) then
      		case State_c is
      			when ST_REG19 =>
      				WLAST <= '1';
      			when ST_REG35 =>
      				WLAST <= '1';
      			when ST_REG51 =>
      				WLAST <= '1';
      			when ST_REG57 =>
      				WLAST <= '1';
      			when others =>
      				WLAST <= '0';
      		end case;
      	end if;
      end process;
   
   
   
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REGA_OUT_NUM_M1 <= (others => '0');
   		REGB_OUT_NUM_M1 <= (others => '0');
   	elsif rising_edge(Clk) then
   		REGA_OUT_NUM_M1 <= REGA_OUT_NUM + X"0001";
   		REGB_OUT_NUM_M1 <= REGB_OUT_NUM + X"0001";
   	end if;
   end process;
   
   


   -- ModuleWare code(v1.9) for instance 'U_0' of 'merge'
   REG_KY <= REG_KY7 & REG_KY65 & REG_KY43 & REG_KY2 & REG_KY1 & REG_KY0;

   -- Instance port mappings.

END struct;
